from common3 import *
R=lambda f:read(O/f)
l=R('classification/section_classification.tsv').query('tumor').rename(columns={'exploratory_cluster':'group'});s=R('tables/section_shapes_near.tsv').merge(l[['section_id','group']]);print(s.groupby(['boundary','near_shape']).size().unstack(fill_value=0).to_string());print('examples',s[s.near_shape.isin(['peak','valley','peak_and_valley'])][['section_id','boundary','near_shape']].head(10).to_string(index=False))
c=R('tables/shape_concordance.tsv').merge(l[['section_id']]);print('concordance',c.describe().loc[['count','mean','50%']].to_string());print(c.query('common_outer_bins>=1').EIN_EIS_minus_nonE.describe())
