a=R('tables/auxiliary_tests.tsv.gz').query("scope=='common_sources'");print(a[a.family.isin(['overall_levels','highlow'])][['measure','g1','g2','n_sources','effect','lo','hi','p','q']].round(4).to_string(index=False));print('sig',a.query("q<0.05")[['family','measure','g1','g2','effect','q']].sort_values('q').head(14).round(4).to_string(index=False));print('niche min',a[a.family.isin(['region','R12'])].nsmallest(3,'q')[['measure','g1','g2','effect','q']])
q=R('tables/curve_tests.tsv');print(q.query("variant=='primary' and domain=='E_inner' and term=='function'")[['boundary','contrast','scale','n_sources','xmin','p','q']].round(4).to_string(index=False));print('sensitivity',q.query("contrast=='C1:C2:C3' and domain=='E_inner' and term=='function'").pivot_table(index=['variant','boundary'],columns='scale',values='q',dropna=True).round(3).to_string());print('stable',q.query("variant=='stable' and contrast=='C1:C2:C3'").status.unique())
print('shape pure',q.query("variant=='primary' and contrast=='C1:C2:C3' and domain=='E_inner' and term=='shape'")[['boundary','scale','q']])
d=R('tables/model_differences.tsv.gz').query("variant=='primary' and contrast=='C1:C2:C3' and domain=='E_inner' and center in [-50,-650] and scale=='raw'");print(d[['boundary','g1','g2','center','diff','lo','hi']].round(4).to_string(index=False));print('mapped',l.unit.nunique(),l.patient_uid.nunique())
print(R('tables/geometry_curve_tests.tsv').query("term=='function'")[['boundary','variant','scale','q']].round(4).to_string(index=False));print('continuous',R('tables/continuous_associations.tsv').query("scope=='source_balanced'").nsmallest(5,'q')[['feature','endpoint','rho','q']]);print(R('classification/univariate.tsv').query("method=='KDE' and Scott_factor==1")[['feature','n_peaks']]);print(l.groupby('group').unit.nunique())

